-- Add the complete 2024 Player's Handbook feat library as manually assigned abilities.
-- Built-in class features remain automatic; feats are never assigned without a DM choice.

begin;

alter table public.abilities add column if not exists ability_kind text not null default 'custom';
alter table public.abilities add column if not exists prerequisite text;
alter table public.abilities add column if not exists repeatable boolean not null default false;
alter table public.abilities add column if not exists dm_edited boolean not null default false;

update public.abilities
set ability_kind = case when is_system then 'class_feature' else 'custom' end
where ability_kind = 'custom';

alter table public.abilities drop constraint if exists abilities_system_metadata_check;
alter table public.abilities drop constraint if exists abilities_kind_check;

alter table public.abilities add constraint abilities_kind_check
  check (ability_kind in ('class_feature', 'feat', 'custom'));

alter table public.abilities add constraint abilities_system_metadata_check
  check (
    not is_system
    or (
      slug is not null
      and (
        (ability_kind = 'class_feature' and class_key is not null and level_required is not null)
        or (ability_kind = 'feat' and class_key is null)
      )
    )
  );

create index if not exists abilities_kind_name_idx
  on public.abilities (ability_kind, category, name);

with feat_data as (
  select value as item
  from jsonb_array_elements($feat_data$[{"slug":"phb24-feat-alert","name":"Alert","category":"Origin Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":1,"action_type":null,"uses":null,"recharge":null,"summary":"Add your Proficiency Bonus to Initiative and trade Initiative results with an ally.","description":"- **Initiative Proficiency.** Add your Proficiency Bonus whenever you roll Initiative.\n- **Initiative Swap.** Immediately after rolling Initiative, you may exchange your result with a willing ally in the same combat. Neither participant can be Incapacitated.","prerequisite":"None","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","origin feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-crafter","name":"Crafter","category":"Origin Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":2,"action_type":null,"uses":null,"recharge":"Long Rest","summary":"Gain three artisan-tool proficiencies, shop at a discount, and quickly craft temporary gear.","description":"- **Tool Training.** Gain proficiency with three different kinds of Artisan’s Tools.\n- **Discount.** Pay 20 percent less when buying nonmagical items.\n- **Fast Crafting.** After a Long Rest, use a proficient tool to make one eligible piece of adventuring gear. It lasts until your next Long Rest. Eligible examples include rope, nets, torches, caltrops, cases, pouches, tents, basic clubs, and similar tool-made gear.","prerequisite":"None","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","origin feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-healer","name":"Healer","category":"Origin Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":3,"action_type":"Utilize Action","uses":null,"recharge":null,"summary":"Use a Healer’s Kit to restore Hit Points and reroll 1s on your healing dice.","description":"- **Battle Medic.** As a Utilize action, expend one use of a Healer’s Kit on a creature within 5 feet. The creature spends a Hit Die; you roll it, and the creature regains that result plus your Proficiency Bonus in Hit Points.\n- **Healing Rerolls.** When a die you roll for a spell or Battle Medic restores Hit Points and shows a 1, reroll it and use the new result.","prerequisite":"None","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","origin feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-lucky","name":"Lucky","category":"Origin Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":4,"action_type":null,"uses":"Proficiency Bonus Luck Points","recharge":"Long Rest","summary":"Spend Luck Points to gain Advantage on your D20 Tests or hinder attacks against you.","description":"You have Luck Points equal to your Proficiency Bonus and regain all of them after a Long Rest. Spend one point to give yourself Advantage on a D20 Test, or to impose Disadvantage on an attack roll made against you. You can spend only one point on a roll.","prerequisite":"None","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","origin feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-magic-initiate","name":"Magic Initiate","category":"Origin Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":5,"action_type":null,"uses":"1 free level 1 casting","recharge":"Long Rest","summary":"Learn two cantrips and one level 1 spell from the Cleric, Druid, or Wizard list.","description":"Choose the Cleric, Druid, or Wizard spell list. Learn two cantrips and prepare one level 1 spell from it. Choose Intelligence, Wisdom, or Charisma as the spellcasting ability. You may cast the level 1 spell once without a slot per Long Rest and may also use your spell slots. When you gain a level, you may replace one chosen spell with another eligible spell from the same list.","prerequisite":"None","repeatable":true,"source":"Player’s Handbook (2024)","tags":["feat","origin feat","2024 rules","repeatable"],"source_type":"book"},{"slug":"phb24-feat-musician","name":"Musician","category":"Origin Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":6,"action_type":null,"uses":"Proficiency Bonus allies","recharge":"Short or Long Rest","summary":"Learn three instruments and grant Heroic Inspiration after rests.","description":"- **Instrument Training.** Gain proficiency with three Musical Instruments.\n- **Encouraging Song.** At the end of a Short or Long Rest, give Heroic Inspiration to a number of allies equal to your Proficiency Bonus.","prerequisite":"None","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","origin feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-savage-attacker","name":"Savage Attacker","category":"Origin Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":7,"action_type":null,"uses":"Once per turn","recharge":null,"summary":"Once per turn, roll a weapon’s damage dice twice and use either result.","description":"Once on each of your turns when you hit with a weapon, roll the weapon’s damage dice twice and use either roll against the target.","prerequisite":"None","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","origin feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-skilled","name":"Skilled","category":"Origin Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":8,"action_type":null,"uses":null,"recharge":null,"summary":"Gain proficiency in any combination of three skills or tools.","description":"Choose three skills, tools, or any combination of the two. You gain proficiency with those choices.","prerequisite":"None","repeatable":true,"source":"Player’s Handbook (2024)","tags":["feat","origin feat","2024 rules","repeatable"],"source_type":"book"},{"slug":"phb24-feat-tavern-brawler","name":"Tavern Brawler","category":"Origin Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":9,"action_type":null,"uses":"Push once per turn","recharge":null,"summary":"Improve Unarmed Strikes, master improvised weapons, and push foes you punch.","description":"- **Enhanced Unarmed Strike.** Your Unarmed Strike can deal 1d4 plus your Strength modifier in Bludgeoning damage, and you may reroll a damage die result of 1.\n- **Improvised Weaponry.** You are proficient with improvised weapons.\n- **Push.** Once per turn when your Unarmed Strike hits and deals damage, push the target 5 feet away if it is no more than one size larger than you.","prerequisite":"None","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","origin feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-tough","name":"Tough","category":"Origin Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":10,"action_type":null,"uses":null,"recharge":null,"summary":"Increase your Hit Point maximum by twice your character level.","description":"Your Hit Point maximum increases by twice your character level when you gain this feat. Each time you gain another level, your maximum increases by 2 more Hit Points.","prerequisite":"None","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","origin feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-ability-score-improvement","name":"Ability Score Improvement","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":1,"action_type":null,"uses":null,"recharge":null,"summary":"Raise one ability by 2 or two abilities by 1, to a maximum of 20.","description":"Increase one ability score by 2, or increase two ability scores by 1 each. This feat cannot raise an ability score above 20.","prerequisite":"Level 4+","repeatable":true,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules","repeatable"],"source_type":"book"},{"slug":"phb24-feat-actor","name":"Actor","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":2,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Charisma and excel at disguises, impersonation, and mimicry.","description":"Increase Charisma by 1, to a maximum of 20. While disguised as a real or fictional person, you have Advantage on Deception or Performance checks made to pass as that person. You can mimic speech and other creature sounds; a listener detects the imitation with a successful Wisdom (Insight) check against DC 8 + your Charisma modifier + your Proficiency Bonus.","prerequisite":"Level 4+; Charisma 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-athlete","name":"Athlete","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":3,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Strength or Dexterity and improve climbing, standing, and running jumps.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. You gain a Climb Speed equal to your Speed, can stand from Prone by spending only 5 feet of movement, and need only a 5-foot run-up for running jumps.","prerequisite":"Level 4+; Strength or Dexterity 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-charger","name":"Charger","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":4,"action_type":null,"uses":"Once per turn","recharge":null,"summary":"Increase Strength or Dexterity, Dash faster, and empower an attack after a straight-line charge.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. Your Speed increases by 10 feet while taking the Dash action. Once per turn, after moving at least 10 feet in a straight line toward a target immediately before hitting it with a melee attack, either add 1d8 to the attack’s damage or push the target up to 10 feet if it is no more than one size larger than you.","prerequisite":"Level 4+; Strength or Dexterity 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-chef","name":"Chef","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":5,"action_type":null,"uses":null,"recharge":"Long Rest or 1 hour","summary":"Increase Constitution or Wisdom and prepare restorative meals and bolstering treats.","description":"Increase Constitution or Wisdom by 1, to a maximum of 20, and gain Cook’s Utensils proficiency. During a Short Rest, feed up to 4 + your Proficiency Bonus creatures; anyone who spends a Hit Die regains an extra 1d8 Hit Points. With 1 hour of work or after a Long Rest, make treats equal to your Proficiency Bonus. For 8 hours, a creature may eat one as a Bonus Action to gain Temporary Hit Points equal to your Proficiency Bonus.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-crossbow-expert","name":"Crossbow Expert","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":6,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Dexterity and use crossbows quickly and effectively at close range.","description":"Increase Dexterity by 1, to a maximum of 20. Ignore the Loading property of crossbows, and attacks with crossbows do not have Disadvantage merely because an enemy is within 5 feet. When the Light property gives you an extra attack with a Light crossbow, add your ability modifier to that attack’s damage if it is not already added.","prerequisite":"Level 4+; Dexterity 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-crusher","name":"Crusher","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":7,"action_type":null,"uses":"Move once per turn","recharge":null,"summary":"Increase Strength or Constitution and control creatures with Bludgeoning damage.","description":"Increase Strength or Constitution by 1, to a maximum of 20. Once per turn after dealing Bludgeoning damage, move the target 5 feet to an unoccupied space if it is no more than one size larger than you. After you score a Critical Hit that deals Bludgeoning damage, attack rolls against that target have Advantage until the start of your next turn.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-defensive-duelist","name":"Defensive Duelist","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":8,"action_type":"Reaction","uses":null,"recharge":null,"summary":"Increase Dexterity and parry melee attacks with a Finesse weapon.","description":"Increase Dexterity by 1, to a maximum of 20. While holding a Finesse weapon, use your Reaction when a melee attack hits you to add your Proficiency Bonus to AC, potentially turning it into a miss. The AC bonus applies against melee attacks until the start of your next turn.","prerequisite":"Level 4+; Dexterity 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-dual-wielder","name":"Dual Wielder","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":9,"action_type":"Bonus Action","uses":null,"recharge":null,"summary":"Increase Strength or Dexterity and fight with a broader pair of one-handed weapons.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. After attacking with a Light weapon during your Attack action, you may make one Bonus Action attack with a different melee weapon that lacks the Two-Handed property; do not add your ability modifier to its damage unless it is negative. You may also draw or stow two non-Two-Handed weapons whenever you could normally draw or stow one.","prerequisite":"Level 4+; Strength or Dexterity 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-durable","name":"Durable","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":10,"action_type":"Bonus Action","uses":null,"recharge":null,"summary":"Increase Constitution, gain Advantage on Death Saves, and spend a Hit Die in combat.","description":"Increase Constitution by 1, to a maximum of 20. You have Advantage on Death Saving Throws. As a Bonus Action, spend and roll one Hit Die to regain Hit Points equal to the roll.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-elemental-adept","name":"Elemental Adept","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":11,"action_type":null,"uses":null,"recharge":null,"summary":"Increase a spellcasting ability and specialize in one elemental damage type.","description":"Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 20. Choose Acid, Cold, Fire, Lightning, or Thunder. Your spells ignore Resistance to the chosen damage type, and when you roll that type of spell damage, treat each damage-die result of 1 as a 2.","prerequisite":"Level 4+; Spellcasting or Pact Magic feature","repeatable":true,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules","repeatable"],"source_type":"book"},{"slug":"phb24-feat-fey-touched","name":"Fey-Touched","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":12,"action_type":null,"uses":"1 free casting of each spell","recharge":"Long Rest","summary":"Increase a mental ability and learn Misty Step plus a level 1 Divination or Enchantment spell.","description":"Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 20. You always have Misty Step and one chosen level 1 Divination or Enchantment spell prepared. Cast each once without a spell slot per Long Rest, or cast them with available spell slots. The increased ability is their spellcasting ability.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-grappler","name":"Grappler","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":13,"action_type":null,"uses":"Punch and grab once per turn","recharge":null,"summary":"Increase Strength or Dexterity and become more dangerous while grappling.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. Once per turn when an Unarmed Strike made as part of the Attack action hits, you may both deal damage and attempt to grapple. You have Advantage on attacks against creatures you are grappling, and moving a grappled creature your size or smaller does not cost extra movement.","prerequisite":"Level 4+; Strength or Dexterity 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-great-weapon-master","name":"Great Weapon Master","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":14,"action_type":"Bonus Action","uses":null,"recharge":null,"summary":"Increase Strength and deal extra damage or follow decisive melee blows with another attack.","description":"Increase Strength by 1, to a maximum of 20. When an Attack-action hit uses a Heavy weapon, add your Proficiency Bonus to its damage. Immediately after a melee weapon scores a Critical Hit or reduces a creature to 0 Hit Points, you may make one attack with that weapon as a Bonus Action.","prerequisite":"Level 4+; Strength 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-heavily-armored","name":"Heavily Armored","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":15,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Strength or Constitution and gain Heavy armor training.","description":"Increase Strength or Constitution by 1, to a maximum of 20. You gain training with Heavy armor.","prerequisite":"Level 4+; Medium armor training","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-heavy-armor-master","name":"Heavy Armor Master","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":16,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Strength or Constitution and reduce physical damage while wearing Heavy armor.","description":"Increase Strength or Constitution by 1, to a maximum of 20. While wearing Heavy armor, reduce incoming Bludgeoning, Piercing, and Slashing damage by your Proficiency Bonus.","prerequisite":"Level 4+; Heavy armor training","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-inspiring-leader","name":"Inspiring Leader","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":17,"action_type":null,"uses":null,"recharge":"Short or Long Rest","summary":"Increase Wisdom or Charisma and grant allies Temporary Hit Points after rests.","description":"Increase Wisdom or Charisma by 1, to a maximum of 20. At the end of a Short or Long Rest, inspire up to six creatures within 30 feet that can see or hear you. Each gains Temporary Hit Points equal to your character level plus the modifier of the ability increased by this feat.","prerequisite":"Level 4+; Wisdom or Charisma 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-keen-mind","name":"Keen Mind","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":18,"action_type":"Bonus Action","uses":null,"recharge":null,"summary":"Increase Intelligence, improve a knowledge skill, and Study as a Bonus Action.","description":"Increase Intelligence by 1, to a maximum of 20. Choose Arcana, History, Investigation, Nature, or Religion: gain proficiency, or Expertise if already proficient. You may take the Study action as a Bonus Action.","prerequisite":"Level 4+; Intelligence 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-lightly-armored","name":"Lightly Armored","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":19,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Strength or Dexterity and gain Light armor and Shield training.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. You gain training with Light armor and Shields.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-mage-slayer","name":"Mage Slayer","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":20,"action_type":null,"uses":"Guarded Mind once per rest","recharge":"Short or Long Rest","summary":"Increase Strength or Dexterity, disrupt Concentration, and resist mental magic.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. A creature you damage has Disadvantage on its saving throw to maintain Concentration. When you fail an Intelligence, Wisdom, or Charisma saving throw, you may turn it into a success once per Short or Long Rest.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-martial-weapon-training","name":"Martial Weapon Training","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":21,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Strength or Dexterity and gain proficiency with Martial weapons.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. You gain proficiency with Martial weapons.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-medium-armor-master","name":"Medium Armor Master","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":22,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Strength or Dexterity and use more Dexterity while wearing Medium armor.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. While wearing Medium armor, you may add up to +3 from Dexterity to AC instead of the normal +2 maximum.","prerequisite":"Level 4+; Medium armor training","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-moderately-armored","name":"Moderately Armored","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":23,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Strength or Dexterity and gain Medium armor training.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. You gain training with Medium armor.","prerequisite":"Level 4+; Light armor training","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-mounted-combatant","name":"Mounted Combatant","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":24,"action_type":null,"uses":null,"recharge":null,"summary":"Increase a physical or perceptive ability and protect and exploit your mount.","description":"Increase Strength, Dexterity, or Wisdom by 1, to a maximum of 20. While mounted, you have Advantage on attacks against unmounted creatures within 5 feet of your mount that are at least one size smaller. Your ridden mount takes no damage on a successful Dexterity save for half damage and half on a failure. You may redirect an attack that hits your mount to yourself while neither of you is Incapacitated.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-observant","name":"Observant","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":25,"action_type":"Bonus Action","uses":null,"recharge":null,"summary":"Increase Intelligence or Wisdom, improve an awareness skill, and Search as a Bonus Action.","description":"Increase Intelligence or Wisdom by 1, to a maximum of 20. Choose Insight, Investigation, or Perception: gain proficiency, or Expertise if already proficient. You may take the Search action as a Bonus Action.","prerequisite":"Level 4+; Intelligence or Wisdom 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-piercer","name":"Piercer","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":26,"action_type":null,"uses":"Reroll once per turn","recharge":null,"summary":"Increase Strength or Dexterity and improve Piercing damage rolls and Critical Hits.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. Once per turn after rolling Piercing damage, reroll one damage die and use the new result. A Critical Hit that deals Piercing damage rolls one additional weapon damage die.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-poisoner","name":"Poisoner","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":27,"action_type":"Bonus Action","uses":null,"recharge":null,"summary":"Increase Dexterity or Intelligence, bypass Poison Resistance, and brew combat poisons.","description":"Increase Dexterity or Intelligence by 1, to a maximum of 20. Your Poison damage ignores Resistance, and you gain Poisoner’s Kit proficiency. With 1 hour, the kit, and 50 GP of materials, brew doses equal to your Proficiency Bonus. Apply a dose to a weapon or ammunition as a Bonus Action; it lasts 1 minute or until it deals damage. The target makes a Constitution save against DC 8 + your Proficiency Bonus + the increased ability’s modifier, taking 2d8 Poison damage and becoming Poisoned until the end of your next turn on a failure.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-polearm-master","name":"Polearm Master","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":28,"action_type":"Bonus Action or Reaction","uses":null,"recharge":null,"summary":"Increase Strength or Dexterity and gain extra and reactive attacks with polearms.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. After attacking with an eligible polearm during the Attack action, make a Bonus Action attack with its opposite end for 1d4 Bludgeoning damage. You may also use your Reaction to make a melee attack with the polearm when a creature enters its reach.","prerequisite":"Level 4+; Strength or Dexterity 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-resilient","name":"Resilient","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":29,"action_type":null,"uses":null,"recharge":null,"summary":"Increase one ability and gain proficiency in its saving throws.","description":"Choose an ability for which you lack saving throw proficiency. Increase it by 1, to a maximum of 20, and gain proficiency in saving throws using it.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-ritual-caster","name":"Ritual Caster","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":30,"action_type":null,"uses":"1 Quick Ritual","recharge":"Long Rest","summary":"Increase a mental ability, prepare level 1 Ritual spells, and cast one ritual quickly each day.","description":"Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 20. Choose level 1 Ritual spells equal to your Proficiency Bonus; they are always prepared and use the increased ability. Add another whenever your Proficiency Bonus rises. Once per Long Rest, cast one prepared Ritual without a slot using its normal casting time instead of the extended Ritual time.","prerequisite":"Level 4+; Intelligence, Wisdom, or Charisma 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-sentinel","name":"Sentinel","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":31,"action_type":"Reaction","uses":null,"recharge":null,"summary":"Increase Strength or Dexterity and punish enemies who disengage or attack your allies.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. Use your Reaction for a melee attack immediately after a creature within 5 feet takes the Disengage action or hits a target other than you. When your Opportunity Attack hits, the target’s Speed becomes 0 for the rest of the turn.","prerequisite":"Level 4+; Strength or Dexterity 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-shadow-touched","name":"Shadow-Touched","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":32,"action_type":null,"uses":"1 free casting of each spell","recharge":"Long Rest","summary":"Increase a mental ability and learn Invisibility plus a level 1 Illusion or Necromancy spell.","description":"Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 20. You always have Invisibility and one chosen level 1 Illusion or Necromancy spell prepared. Cast each once without a spell slot per Long Rest, or cast them with available spell slots. The increased ability is their spellcasting ability.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-sharpshooter","name":"Sharpshooter","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":33,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Dexterity and negate common penalties on ranged weapon attacks.","description":"Increase Dexterity by 1, to a maximum of 20. Your ranged weapon attacks ignore Half and Three-Quarters Cover, do not have Disadvantage merely because an enemy is within 5 feet, and do not have Disadvantage at long range.","prerequisite":"Level 4+; Dexterity 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-shield-master","name":"Shield Master","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":34,"action_type":"Reaction","uses":null,"recharge":null,"summary":"Increase Strength and use your Shield to shove foes or avoid area damage.","description":"Increase Strength by 1, to a maximum of 20. Once per turn after an Attack-action melee hit against a creature within 5 feet, bash it with your equipped Shield. It makes a Strength save against DC 8 + your Strength modifier + Proficiency Bonus; on a failure, push it 5 feet or knock it Prone. When an effect permits a Dexterity save for half damage, use your Reaction while holding a Shield to take no damage on a success.","prerequisite":"Level 4+; Shield training","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-skill-expert","name":"Skill Expert","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":35,"action_type":null,"uses":null,"recharge":null,"summary":"Increase any ability, learn one skill, and gain Expertise in another.","description":"Increase one ability by 1, to a maximum of 20. Gain proficiency in one skill, then choose one skill in which you are proficient and gain Expertise with it.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-skulker","name":"Skulker","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":36,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Dexterity and become harder to detect while fighting from concealment.","description":"Increase Dexterity by 1, to a maximum of 20. Gain Blindsight with a 10-foot range, have Advantage on Dexterity (Stealth) checks made as part of the Hide action during combat, and remain hidden when an attack roll misses.","prerequisite":"Level 4+; Dexterity 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-slasher","name":"Slasher","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":37,"action_type":null,"uses":"Speed reduction once per turn","recharge":null,"summary":"Increase Strength or Dexterity and hinder creatures with Slashing damage.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. Once per turn after dealing Slashing damage, reduce the target’s Speed by 10 feet until the start of your next turn. A Critical Hit that deals Slashing damage gives the target Disadvantage on attack rolls until the start of your next turn.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-speedy","name":"Speedy","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":38,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Dexterity or Constitution, move faster, and evade difficult terrain and Opportunity Attacks.","description":"Increase Dexterity or Constitution by 1, to a maximum of 20. Your Speed increases by 10 feet. Difficult Terrain does not cost extra movement while you Dash, and Opportunity Attacks against you have Disadvantage.","prerequisite":"Level 4+; Dexterity or Constitution 13+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-spell-sniper","name":"Spell Sniper","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":39,"action_type":null,"uses":null,"recharge":null,"summary":"Increase a spellcasting ability and improve the reach and reliability of spell attacks.","description":"Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 20. Spell attack rolls ignore Half and Three-Quarters Cover, do not have Disadvantage merely because an enemy is within 5 feet, and gain 60 feet of range when the spell normally has a range of at least 10 feet.","prerequisite":"Level 4+; Spellcasting or Pact Magic feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-telekinetic","name":"Telekinetic","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":40,"action_type":"Bonus Action","uses":null,"recharge":null,"summary":"Increase a mental ability, improve Mage Hand, and push or pull creatures at range.","description":"Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 20. You always have Mage Hand prepared; its hand is invisible, needs no Verbal or Somatic components, and its range increases by 30 feet if you already knew it. As a Bonus Action, force a creature within 30 feet to make a Strength save or move it 5 feet toward or away from you; a willing creature may fail automatically.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-telepathic","name":"Telepathic","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":41,"action_type":null,"uses":"1 free Detect Thoughts","recharge":"Long Rest","summary":"Increase a mental ability, communicate telepathically, and gain Detect Thoughts.","description":"Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 20. Speak telepathically to a creature you can see within 60 feet if it knows at least one language; this communication is one-way. You always have Detect Thoughts prepared and may cast it once without a spell slot per Long Rest or with your spell slots.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-war-caster","name":"War Caster","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":42,"action_type":"Reaction","uses":null,"recharge":null,"summary":"Increase a spellcasting ability and cast reliably while armed or under pressure.","description":"Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 20. You have Advantage on Constitution saves to maintain Concentration. When a creature provokes an Opportunity Attack by leaving your reach, use your Reaction to cast a one-action spell that targets only that creature. You may perform Somatic components while weapons or a Shield occupy either hand.","prerequisite":"Level 4+; Spellcasting or Pact Magic feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-weapon-master","name":"Weapon Master","category":"General Feat","ability_kind":"feat","class_key":null,"level_required":4,"feature_order":43,"action_type":null,"uses":null,"recharge":"Long Rest to change","summary":"Increase Strength or Dexterity and learn one weapon’s mastery property.","description":"Increase Strength or Dexterity by 1, to a maximum of 20. Choose one Simple or Martial weapon with which you are proficient; you may use its mastery property. You may change the chosen weapon after a Long Rest.","prerequisite":"Level 4+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","general feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-archery","name":"Archery","category":"Fighting Style Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":1,"action_type":null,"uses":null,"recharge":null,"summary":"Gain a +2 bonus to attack rolls made with Ranged weapons.","description":"You gain a +2 bonus to attack rolls you make with Ranged weapons.","prerequisite":"Fighting Style feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","fighting style feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-blind-fighting","name":"Blind Fighting","category":"Fighting Style Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":2,"action_type":null,"uses":null,"recharge":null,"summary":"Gain Blindsight within 10 feet.","description":"You have Blindsight with a range of 10 feet.","prerequisite":"Fighting Style feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","fighting style feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-defense","name":"Defense","category":"Fighting Style Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":3,"action_type":null,"uses":null,"recharge":null,"summary":"Gain +1 AC while wearing armor.","description":"While wearing Light, Medium, or Heavy armor, you gain a +1 bonus to Armor Class.","prerequisite":"Fighting Style feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","fighting style feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-dueling","name":"Dueling","category":"Fighting Style Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":4,"action_type":null,"uses":null,"recharge":null,"summary":"Deal +2 damage while wielding one melee weapon in one hand.","description":"While holding a melee weapon in one hand and no other weapons, gain +2 to damage rolls with that weapon. A Shield does not prevent this benefit.","prerequisite":"Fighting Style feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","fighting style feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-great-weapon-fighting","name":"Great Weapon Fighting","category":"Fighting Style Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":5,"action_type":null,"uses":null,"recharge":null,"summary":"Treat 1s and 2s on two-handed weapon damage dice as 3s.","description":"When you roll damage for a melee weapon held in two hands, treat any 1 or 2 on the weapon’s damage dice as a 3. The weapon must have the Two-Handed or Versatile property to qualify.","prerequisite":"Fighting Style feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","fighting style feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-interception","name":"Interception","category":"Fighting Style Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":6,"action_type":"Reaction","uses":null,"recharge":null,"summary":"Use your Reaction to reduce damage dealt to a nearby ally.","description":"When a creature you can see hits another creature within 5 feet of you with an attack, use your Reaction to reduce the target’s damage by 1d10 + your Proficiency Bonus. You must hold a Shield or a Simple or Martial weapon.","prerequisite":"Fighting Style feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","fighting style feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-protection","name":"Protection","category":"Fighting Style Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":7,"action_type":"Reaction","uses":null,"recharge":null,"summary":"Use a Shield to hinder attacks against a nearby ally.","description":"While holding a Shield, use your Reaction when a creature you can see attacks someone other than you within 5 feet. The triggering attack and later attacks against that ally have Disadvantage until the start of your next turn, provided you stay within 5 feet of the ally.","prerequisite":"Fighting Style feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","fighting style feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-thrown-weapon-fighting","name":"Thrown Weapon Fighting","category":"Fighting Style Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":8,"action_type":null,"uses":null,"recharge":null,"summary":"Deal +2 damage with ranged attacks using Thrown weapons.","description":"When you hit with a ranged attack using a weapon that has the Thrown property, gain +2 to the damage roll.","prerequisite":"Fighting Style feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","fighting style feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-two-weapon-fighting","name":"Two-Weapon Fighting","category":"Fighting Style Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":9,"action_type":null,"uses":null,"recharge":null,"summary":"Add your ability modifier to the Light property’s extra attack.","description":"When the Light property gives you an extra attack, add your ability modifier to that attack’s damage if it is not already included.","prerequisite":"Fighting Style feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","fighting style feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-unarmed-fighting","name":"Unarmed Fighting","category":"Fighting Style Feat","ability_kind":"feat","class_key":null,"level_required":null,"feature_order":10,"action_type":null,"uses":"Grapple damage once per turn","recharge":null,"summary":"Improve your Unarmed Strikes and damage creatures you grapple.","description":"Your damaging Unarmed Strikes deal 1d6 + Strength modifier Bludgeoning damage, or 1d8 + Strength modifier while neither hand holds a weapon or Shield. Once per turn, deal 1d4 Bludgeoning damage to one creature you are grappling.","prerequisite":"Fighting Style feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","fighting style feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-combat-prowess","name":"Boon of Combat Prowess","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":1,"action_type":null,"uses":"Once per round","recharge":null,"summary":"Increase any ability and turn one missed attack per turn into a hit.","description":"Increase one ability by 1, to a maximum of 30. When an attack roll misses, you may make it hit instead. After using this benefit, you cannot use it again until the start of your next turn.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-dimensional-travel","name":"Boon of Dimensional Travel","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":2,"action_type":null,"uses":null,"recharge":null,"summary":"Increase any ability and teleport after taking the Attack or Magic action.","description":"Increase one ability by 1, to a maximum of 30. Immediately after taking the Attack or Magic action, teleport up to 30 feet to an unoccupied space you can see.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-energy-resistance","name":"Boon of Energy Resistance","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":3,"action_type":"Reaction","uses":null,"recharge":null,"summary":"Increase any ability, gain two energy Resistances, and redirect their damage.","description":"Increase one ability by 1, to a maximum of 30. Choose two of Acid, Cold, Fire, Lightning, Necrotic, Poison, Psychic, Radiant, or Thunder; gain Resistance to them and change the choices after a Long Rest. When one of those types damages you, use your Reaction to target a visible creature within 60 feet that lacks Total Cover. It makes a Dexterity save against DC 8 + your Constitution modifier + Proficiency Bonus, taking 2d12 + your Constitution modifier of that type on a failure.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-fate","name":"Boon of Fate","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":4,"action_type":null,"uses":"Once until recharged","recharge":"Initiative, Short Rest, or Long Rest","summary":"Increase any ability and alter a nearby creature’s successful or failed D20 Test by 2d4.","description":"Increase one ability by 1, to a maximum of 30. When you or a creature within 60 feet succeeds or fails a D20 Test, roll 2d4 and add or subtract the total from the d20, potentially changing the result. Recharge this benefit when you roll Initiative or finish a Short or Long Rest.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-fortitude","name":"Boon of Fortitude","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":5,"action_type":null,"uses":"Extra healing once per turn","recharge":null,"summary":"Increase any ability, gain 40 maximum Hit Points, and improve healing received.","description":"Increase one ability by 1, to a maximum of 30. Your Hit Point maximum rises by 40. Once per turn when you regain Hit Points, regain additional Hit Points equal to your Constitution modifier.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-irresistible-offense","name":"Boon of Irresistible Offense","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":6,"action_type":null,"uses":null,"recharge":null,"summary":"Increase Strength or Dexterity, bypass physical Resistance, and empower natural 20s.","description":"Increase Strength or Dexterity by 1, to a maximum of 30. Your Bludgeoning, Piercing, and Slashing damage ignores Resistance. When an attack roll’s d20 shows 20, deal extra damage equal to the ability score increased by this feat; the extra damage matches the attack’s type.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-recovery","name":"Boon of Recovery","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":7,"action_type":"Bonus Action","uses":"10d10 healing pool; Last Stand once","recharge":"Long Rest","summary":"Increase any ability, survive a fall to 0 Hit Points, and draw healing from a d10 pool.","description":"Increase one ability by 1, to a maximum of 30. Once per Long Rest when you would fall to 0 Hit Points, remain at 1 and then regain half your Hit Point maximum. You also have a pool of ten d10s; as a Bonus Action, spend any number, roll them, and regain that many Hit Points. The pool refreshes after a Long Rest.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-skill","name":"Boon of Skill","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":8,"action_type":null,"uses":null,"recharge":null,"summary":"Increase any ability, gain every skill proficiency, and gain one Expertise.","description":"Increase one ability by 1, to a maximum of 30. Gain proficiency in every skill. Choose one skill in which you do not already have Expertise and gain Expertise with it.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-speed","name":"Boon of Speed","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":9,"action_type":"Bonus Action","uses":null,"recharge":null,"summary":"Increase any ability, add 30 feet to Speed, and escape danger as a Bonus Action.","description":"Increase one ability by 1, to a maximum of 30. Your Speed increases by 30 feet. As a Bonus Action, take the Disengage action and also end the Grappled condition on yourself.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-spell-recall","name":"Boon of Spell Recall","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":10,"action_type":null,"uses":null,"recharge":null,"summary":"Increase a spellcasting ability and sometimes retain level 1–4 spell slots when casting.","description":"Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 30. Whenever you cast using a level 1–4 spell slot, roll 1d4. If the roll equals the slot’s level, the slot is not expended.","prerequisite":"Level 19+; Spellcasting feature","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-the-night-spirit","name":"Boon of the Night Spirit","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":11,"action_type":"Bonus Action","uses":null,"recharge":null,"summary":"Increase any ability and become invisible and damage-resistant in dim light or darkness.","description":"Increase one ability by 1, to a maximum of 30. In Dim Light or Darkness, use a Bonus Action to become Invisible until immediately after you take an action, Bonus Action, or Reaction. While in Dim Light or Darkness, you also have Resistance to every damage type except Psychic and Radiant.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"},{"slug":"phb24-feat-boon-of-truesight","name":"Boon of Truesight","category":"Epic Boon Feat","ability_kind":"feat","class_key":null,"level_required":19,"feature_order":12,"action_type":null,"uses":null,"recharge":null,"summary":"Increase any ability and gain Truesight to 60 feet.","description":"Increase one ability by 1, to a maximum of 30. You gain Truesight with a range of 60 feet.","prerequisite":"Level 19+","repeatable":false,"source":"Player’s Handbook (2024)","tags":["feat","epic boon feat","2024 rules"],"source_type":"book"}]$feat_data$::jsonb)
)
insert into public.abilities (
  slug,
  name,
  category,
  ability_kind,
  class_key,
  level_required,
  feature_order,
  is_system,
  source_type,
  action_type,
  uses,
  recharge,
  summary,
  description,
  prerequisite,
  repeatable,
  source,
  tags,
  created_by
)
select
  item->>'slug',
  item->>'name',
  item->>'category',
  item->>'ability_kind',
  nullif(item->>'class_key', ''),
  (item->>'level_required')::integer,
  (item->>'feature_order')::integer,
  true,
  item->>'source_type',
  nullif(item->>'action_type', ''),
  nullif(item->>'uses', ''),
  nullif(item->>'recharge', ''),
  nullif(item->>'summary', ''),
  item->>'description',
  nullif(item->>'prerequisite', ''),
  coalesce((item->>'repeatable')::boolean, false),
  nullif(item->>'source', ''),
  array(select jsonb_array_elements_text(item->'tags')),
  null
from feat_data
on conflict (slug) do update set
  name = excluded.name,
  category = excluded.category,
  ability_kind = excluded.ability_kind,
  class_key = excluded.class_key,
  level_required = excluded.level_required,
  feature_order = excluded.feature_order,
  is_system = true,
  source_type = excluded.source_type,
  action_type = excluded.action_type,
  uses = excluded.uses,
  recharge = excluded.recharge,
  summary = excluded.summary,
  description = excluded.description,
  prerequisite = excluded.prerequisite,
  repeatable = excluded.repeatable,
  source = excluded.source,
  tags = excluded.tags,
  updated_at = now()
where not public.abilities.dm_edited;

create or replace function public.dm_set_ability_override(
  p_character_id uuid,
  p_ability_id uuid,
  p_enabled boolean
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_character_class text;
  v_character_level integer;
  v_ability_class text;
  v_required_level integer;
  v_feature_order integer;
  v_is_system boolean;
  v_ability_kind text;
  v_is_eligible boolean;
  v_sort_order integer;
begin
  if not public.is_dm() then
    raise exception 'Only the DM can change ability assignments.';
  end if;

  select
    c.class_key,
    c.level,
    a.class_key,
    a.level_required,
    a.feature_order,
    a.is_system,
    a.ability_kind
  into
    v_character_class,
    v_character_level,
    v_ability_class,
    v_required_level,
    v_feature_order,
    v_is_system,
    v_ability_kind
  from public.characters c
  cross join public.abilities a
  where c.id = p_character_id
    and a.id = p_ability_id;

  if not found then
    raise exception 'Character or ability not found.';
  end if;

  v_is_eligible := v_is_system
    and v_ability_kind = 'class_feature'
    and v_ability_class = v_character_class
    and v_required_level <= v_character_level;

  v_sort_order := case
    when v_ability_kind = 'class_feature' then (coalesce(v_required_level, 0) * 100) + v_feature_order
    when v_ability_kind = 'feat' then 50000 + v_feature_order
    else 60000 + v_feature_order
  end;

  if p_enabled then
    insert into public.character_abilities (
      character_id,
      ability_id,
      sort_order,
      assignment_type,
      is_enabled
    )
    values (
      p_character_id,
      p_ability_id,
      v_sort_order,
      case when v_is_eligible then 'automatic' else 'dm_included' end,
      true
    )
    on conflict (character_id, ability_id) do update set
      sort_order = excluded.sort_order,
      assignment_type = excluded.assignment_type,
      is_enabled = true;
  elsif v_is_eligible then
    insert into public.character_abilities (
      character_id,
      ability_id,
      sort_order,
      assignment_type,
      is_enabled
    )
    values (
      p_character_id,
      p_ability_id,
      v_sort_order,
      'dm_excluded',
      false
    )
    on conflict (character_id, ability_id) do update set
      sort_order = excluded.sort_order,
      assignment_type = 'dm_excluded',
      is_enabled = false;
  else
    delete from public.character_abilities
    where character_id = p_character_id
      and ability_id = p_ability_id;
  end if;
end;
$$;

revoke all on function public.dm_set_ability_override(uuid, uuid, boolean) from public, anon;
grant execute on function public.dm_set_ability_override(uuid, uuid, boolean) to authenticated;

commit;
